const lv_image_dsc_t *picto(picto_t id, int size)
{
    static const struct
    {
        picto_t id;
        int size;
        const lv_image_dsc_t *img;
    } MAP[] = {
        {PICTO_NOZZLE, 24, &IMG_NOZZLE_24},
        {PICTO_BED, 24, &IMG_BED_24},
        {PICTO_CHAMBER, 24, &IMG_CHAMBER_24},
        {PICTO_FILE, 16, &IMG_FILE_16},
        {PICTO_CLOCK, 16, &IMG_CLOCK_16},
        {PICTO_FLAG, 16, &IMG_FLAG_16},
        {PICTO_BULB, 24, &IMG_BULB_24},
    };
    for (size_t i = 0; i < sizeof MAP / sizeof MAP[0]; i++)
    {
        if (MAP[i].id == id && MAP[i].size == size)
        {
            return MAP[i].img;
        }
    }
    return NULL;
}

lv_obj_t *picto_create(lv_obj_t *parent, picto_t id, int size, lv_color_t color)
{
    lv_obj_t *im = lv_image_create(parent);
    lv_image_set_src(im, picto(id, size));
    lv_obj_set_style_image_recolor(im, color, 0);
    lv_obj_set_style_image_recolor_opa(im, LV_OPA_COVER, 0);
    lv_obj_set_clickable(im, false);
    return im;
}
